from click.testing import CliRunner
base = {'removed': 'old', 'restored': None, 'none': None, 'empty': '', 'kept': 'value'}
overrides = {'removed': None, 'restored': 'new', 'added': None}
runner = CliRunner(env=base)
merged = dict(base, **overrides)
assert runner.make_env(overrides) == merged
assert runner.make_env(overrides, strip_none=False) == merged
assert runner.make_env(overrides, strip_none=True) == {'restored': 'new', 'empty': '', 'kept': 'value'}
assert runner.make_env(strip_none=True) == {'removed': 'old', 'empty': '', 'kept': 'value'}
assert runner.make_env({}, strip_none=True) == runner.make_env(strip_none=True)
assert CliRunner().make_env(strip_none=True) == {}
assert base == {'removed': 'old', 'restored': None, 'none': None, 'empty': '', 'kept': 'value'}
assert overrides == {'removed': None, 'restored': 'new', 'added': None}
try:
    runner.make_env(None, True)
except TypeError:
    pass
else:
    raise AssertionError('strip_none must be keyword-only')
'@ | python -B -; if ($LASTEXITCODE -eq 0) { python -B -m pytest -q -p no:cacheprovider tests\test_testing.py }; git diff --check; git status --short

